/// The index of a named entry, for the resolver that turns an import
/// into an index at compile time.
///
/// A binary search over a sorted array, and the ONLY place a name is
/// matched. It runs while compiling, never while running: a call site
/// holds the index this returned.
pub fn index_of(name: &str) -> Option<EntryIndex> {
    ENTRIES
        .binary_search_by(|entry| entry.name.cmp(name))
        .ok()
        .map(|index| index as EntryIndex)
}
